import{_ as r,o,c as a,a2 as e}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"長期メモリ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/memory.md","filePath":"ja/guides/memory.md","lastUpdated":1792323081000}'),n={name:"ja/guides/memory.md"};function i(l,t,s,d,h,g){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="長期メモリ" tabindex="-1">長期メモリ <a class="header-anchor" href="#長期メモリ" aria-label="Permalink to &quot;長期メモリ&quot;">​</a></h1><p>Memoh の構造化された長期メモリにより、Bot は<strong>複数のセッション</strong>をまたいで、以前に残した事実を活用できます。<strong>メモリ</strong> タブを使う前に、まず Bot に <strong>Memory Provider</strong> を設定してください。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ol><li><a href="./../integrations/providers/memory/builtin.html">メモリプロバイダー</a> で 1 つ作成します（内蔵、Mem0、OpenViking など）。</li><li>Bot の <strong>一般</strong> タブを開きます。</li><li><strong>Memory Provider</strong> で選択します。</li><li>保存します。</li></ol><p>プロバイダーを選択していなければ、使用中のメモリバックエンドはありません。</p><hr><h2 id="何をするものか" tabindex="-1">何をするものか <a class="header-anchor" href="#何をするものか" aria-label="Permalink to &quot;何をするものか&quot;">​</a></h2><p>メモリエントリの保存・取得・検索は、現在のプロバイダーが実装します。プロバイダーのタイプによって、内蔵のメモリグラフ、pgvector のベクトル、外部 API のいずれかになります。ユーザーがメッセージを送ると、Memoh は関連するメモリを取り出して、そのときのコンテキストに含めようとします。</p><p>このページで扱うのは<strong>長期メモリ</strong>です。<strong>セッションが長くなりすぎた</strong>ときに短くするのは別の話で、<a href="./compaction.html">コンテキスト圧縮</a> を参照してください。</p><hr><h2 id="画面での操作" tabindex="-1">画面での操作 <a class="header-anchor" href="#画面での操作" aria-label="Permalink to &quot;画面での操作&quot;">​</a></h2><h3 id="メモリの作成" tabindex="-1">メモリの作成 <a class="header-anchor" href="#メモリの作成" aria-label="Permalink to &quot;メモリの作成&quot;">​</a></h3><ul><li><strong>New Memory</strong>：手入力で 1 件作成します。</li><li><strong>From Conversation</strong>：既存の会話からメモリとして抽出します。</li></ul><h3 id="検索と管理" tabindex="-1">検索と管理 <a class="header-anchor" href="#検索と管理" aria-label="Permalink to &quot;検索と管理&quot;">​</a></h3><ul><li><strong>Search</strong>：id またはテキストで絞り込みます。</li><li><strong>Edit</strong>：内容を編集します。</li><li><strong>Delete</strong>：不要になったら削除します。</li></ul><hr><h2 id="メモリ圧縮-注意-セッション圧縮ではありません" tabindex="-1">メモリ圧縮（注意：セッション圧縮ではありません） <a class="header-anchor" href="#メモリ圧縮-注意-セッション圧縮ではありません" aria-label="Permalink to &quot;メモリ圧縮（注意：セッション圧縮ではありません）&quot;">​</a></h2><p>メモリが溜まってきたら、<strong>メモリ</strong> タブで<strong>ストレージ側</strong>に <strong>Compact</strong> を実行できます。重複の統合、古いエントリの除去、ノイズの圧縮を行います。</p><p>パラメーター：</p><ul><li><strong>Ratio</strong>：圧縮率。<code>0.8</code>、<code>0.5</code>、<code>0.3</code> など。値が低いほど積極的に圧縮します。</li><li><strong>Decay Days</strong>：任意。この日数より古いメモリだけを圧縮対象にし、新しいメモリには触れません。</li></ul><p>これは <a href="./compaction.html">コンテキスト圧縮</a> とは別物です。後者は<strong>単一のセッション</strong>内で prompt を短くするもので、ストアにある長期メモリエントリの保存のされ方や統合結果は変更しません。</p><hr><h2 id="rebuild" tabindex="-1">Rebuild <a class="header-anchor" href="#rebuild" aria-label="Permalink to &quot;Rebuild&quot;">​</a></h2><p><strong>Rebuild</strong> は現在の設定で<strong>ストア全体を再インデックス</strong>します。embedding モデルを変更したとき、インデックスが不整合になったとき、新しい設定で全件を処理し直したいときに便利です。進捗は画面で確認できます。</p><hr><h2 id="ステータス" tabindex="-1">ステータス <a class="header-anchor" href="#ステータス" aria-label="Permalink to &quot;ステータス&quot;">​</a></h2><p><strong>メモリ</strong> タブには、その Bot のメモリバックエンドの <strong>Connected / Error</strong> が表示されます。トラブルシューティングの際は、まずここを確認してください。</p><hr><h2 id="使用状況" tabindex="-1">使用状況 <a class="header-anchor" href="#使用状況" aria-label="Permalink to &quot;使用状況&quot;">​</a></h2><p><strong>合計件数</strong>や<strong>インデックスが追いついているか</strong>などを確認できます。状況を把握してから方針を調整しましょう。</p><hr><h2 id="「セッション内の会話」との比較" tabindex="-1">「セッション内の会話」との比較 <a class="header-anchor" href="#「セッション内の会話」との比較" aria-label="Permalink to &quot;「セッション内の会話」との比較&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>対象範囲</th><th>操作場所</th><th>変更内容</th></tr></thead><tbody><tr><td><strong>メモリ圧縮</strong></td><td>長期メモリプロバイダー</td><td>メモリ タブ</td><td>ストア内のエントリの統合・整理のされ方を変える</td></tr><tr><td><strong>コンテキスト圧縮</strong></td><td>現在のセッション</td><td>ステータス表示または <code>/compact</code></td><td>要約によって<strong>このセッション</strong>の履歴を短くし、以降のターンで使う</td></tr></tbody></table><p>「セッションをまたぐノイズ」を減らしてメモリストアを整理したい → <strong>メモリ圧縮</strong> を使います。<br> 「このセッションが長くなりすぎた」を解消したい → <a href="./compaction.html">コンテキスト圧縮</a> を使います。</p><hr><h2 id="bot-との関係" tabindex="-1">Bot との関係 <a class="header-anchor" href="#bot-との関係" aria-label="Permalink to &quot;Bot との関係&quot;">​</a></h2><ul><li>チャット中は、設定に従ってメモリを検索します。</li><li>どのバックエンドや embedding を使うかは<strong>プロバイダー</strong>側で設定します。<a href="./../integrations/providers/memory/builtin.html">メモリプロバイダー</a> を参照してください。</li><li>長期メモリは、Bot の「個性と事実」を支える大きな情報源です。</li></ul>',37)])])}const u=r(n,[["render",i]]);export{m as __pageData,u as default};
